// EvidenceFieldRow is one filled form field on the application evidence page.
type EvidenceFieldRow struct {
	Page   int
	Label  string
	Value  string
	Source string
	Kind   string // field kind; a checkbox shows as yes or no
}

// Shown is the value as the user reads it: a checkbox is yes or no, not the browser's "checked".
func (f EvidenceFieldRow) Shown(ctx context.Context) string {
	switch f.Kind {
	case "checkbox", "aria_checkbox":
		if f.Value == "checked" {
			return T(ctx, "evidence.fields.yes")
		}
		return T(ctx, "evidence.fields.no")
	default:
		return f.Value
	}
}

// TimelineRow is one chronological event or checkpoint on the application evidence page.
type TimelineRow struct {
	At            time.Time
	Kind          string
	Step          string
	FromState     string
	ToState       string
	Actor         string
	Page          int
	URL           string
	Detail        string
	ScreenshotURL string
}

// SuggestionData holds a status suggestion for the application view.
type SuggestionData struct {
	ID             string
	Category       string
	SuggestedState string
	Reasons        []string
	From           string
	Subject        string
}

